+
+afterEach(async () => {
+  // Clean up worktrees before removing temp dir
+  try {
+    execSync("git worktree list --porcelain", {
+      cwd: tempDir,
+      encoding: "utf-8",
+    });
+    execSync(`git worktree remove ${SESSIONS_WORKTREE_DIR} --force 2>/dev/null || true`, {
