+
+// AC: @session-branch-worktree ac-init
+describe("session branch initialization", () => {
+  it("creates orphan branch and worktree at .kspec-sessions/", async () => {
+    // AC: @session-branch-worktree ac-init
+    const result = await initializeSessionBranch(tempDir);
+
